import React, { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';
import Header from './Header';
import '../Components/Itempageyt.css';
import Footer from './Footer';
import axios from 'axios';

const ItemPage = () => {
    const [jewel, setJewel] = useState(null);
    const [quantity, setQuantity] = useState(1);
    const [message, setMessage] = useState('');
    const location = useLocation();  // Get location object from react-router
    const { jewelId } = location.state || {}; // Assuming jewelId is passed via location.state

    useEffect(() => {
        if (jewelId) {
            axios.get(`http://localhost:5000/api/jewellry/${jewelId}`)
                .then(response => {
                    setJewel(response.data);
                })
                .catch(err => {
                    console.error(err);
                    // Handle error case
                });
        }
    }, [jewelId]);

    if (!jewel) {
        return <div>Item not found.</div>;
    }

    const incrementQuantity = () => {
        setQuantity(quantity + 1);
    };

    const decrementQuantity = () => {
        if (quantity > 1) {
            setQuantity(quantity - 1);
        }
    };

    const handleAddToCart = () => {
        setMessage(`🪞🪷 ${quantity} ${jewel.name} added to cart! 🪷🪕`);
        setTimeout(() => {
            setMessage('');
        }, 3000);
    };

    const subtotal = jewel.price * quantity;

    return (
        <div className="productful">
            <Header />
            <div className="item-page">
                <div className="image-container">
                    {/* Display images and details */}
                    <div className="sub-images-container">
                        {/* Assuming jewel.imageUrl contains image filenames */}
                        <img src={`./images/${jewel.images[0]}`} alt={jewel.name} />
                    </div>
                </div>

                <div className="details-container">
                    <h1 className="Name-of-saree">{jewel.name}</h1>
                    <h3 className="item-price">₹{jewel.price}</h3>
                    <h3 className="item-description">{jewel.description}</h3>
                    <button className="add-to-cart-button" onClick={handleAddToCart}>Add to Cart</button>
                    {message && <div className="popup-message">{message}</div>}

                    {/* Quantity control */}
                    <div className="quantity-control">
                        <button className="quantity-button" onClick={decrementQuantity}>-</button>
                        <span className="quantity">{quantity}</span>
                        <button className="quantity-button" onClick={incrementQuantity}>+</button>
                    </div>
                </div>
            </div>
            <Footer />
        </div>
    );
};

export default ItemPage;
